import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P01-Programming-thinking/18-How-to-calculate-PI-with-a-handful-of-rice.html","title":"18-用撒米的方法计算 π，你信吗？","lang":"zh-CN","frontmatter":{"title":"18-用撒米的方法计算 π，你信吗？","icon":"read","date":"2025-04-20T09:54:52.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1748754423000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":18,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":4}],"changelog":[{"hash":"ff4587c74d1c76d3aac787d3c96ea9dd9fecd743","time":1748754423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更改文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"384179e142a7ff3950112f0208d0fa34ebf3c18b","time":1745156029000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"inti"},{"hash":"da795db327748b3ab1d46eb5860fdb4320456597","time":1745151780000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"51d62c66fc6dfda8edd3d988538be7bd72a6ffd3","time":1745151198000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改标题"},{"hash":"62fac9bdfb35f8a4682b4bb3a3b0e01387aeeb89","time":1745151131000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"e625eb4ba78b6c8b8ef37f1e296534410d117dc1","time":1745138429000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"change"},{"hash":"828e16db25e25476983f4f84fecb5b622ca180a8","time":1745133942000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"up"},{"hash":"8d340cf97f9d808ed88661d5435cdd0d6d04a049","time":1745114131000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"init"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"f14b0cca174ae138ce78063f95445916775cebdb","time":1718679320000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"e6ce4e085767c4f5b781fafab34fce9bb8a77757","time":1717922615000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"192.168.3.12"},{"hash":"698822ef18765f0a40a5fe8d17c8e37745f728e7","time":1717398270000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"2024-06-03 15:03:05"},{"hash":"772c411a931f42f9f56579305c16a96c1c834525","time":1675582584000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"e6a0f505dee0408ae039742ed8b7c873f3ccba3b","time":1675328574000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"添加 Python 教程"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":7.5,"words":2251},"filePathRelative":"column/Python-Programming-Course/P01-Programming-thinking/18-How-to-calculate-PI-with-a-handful-of-rice.md"}`),a={name:`18-How-to-calculate-PI-with-a-handful-of-rice.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<figure><img src="/assets/raw-20250420192845247-BOQedr2w.png" alt="圆周率 π" tabindex="0" loading="lazy"><figcaption>圆周率 π</figcaption></figure><p>小时候学数学，有个神秘又可爱的符号经常出现在题目里：π（读作“派”）。它可不是咱们吃的水果派，而是一个连接“圆”世界的大明星——<strong>圆周率</strong>。</p><p>简单来说，如果你拿一根线把一个圆的边缘绕一圈，然后和这个圆的直径比一比，这个比值就是 π。不管你画的大圆、小圆、手画的还是印刷的，这个比值神奇地永远差不多等于3.14多点。而这个神秘数字，也让古今中外的数学家们挠破了头。</p><figure><img src="/assets/raw-CCYo2rzA.png" alt="祖冲之" tabindex="0" loading="lazy"><figcaption>祖冲之</figcaption></figure><p>在中国的历史里，早在1500多年前，就有一位超级数学天才登场——<strong>祖冲之</strong>。他用了特别复杂的方法，算出了 π 的前七位小数，这在当时简直是“数学界的登月”，而他的记录，保持了800年之久！</p><p>但问题来了，祖冲之用的方法叫“割圆术”，操作极其复杂，不是咱们动动脑筋就能搞定的。不过别担心，咱们还有“现代魔法”——用<strong>编程的脑子</strong>、<strong>实验的思路</strong>，再配上一把大米，居然也能估出 π！</p><h2 id="_1-用大米当尺子-听起来是不是很疯狂" tabindex="-1"><a class="header-anchor" href="#_1-用大米当尺子-听起来是不是很疯狂"><span>1. 用大米当尺子，听起来是不是很疯狂？</span></a></h2><figure><img src="/assets/lon-BWOUxiNU.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>想象一下，你的手机屏幕上有一个龙的图案。你想知道这只可爱的龙占了多少屏幕面积，却发现它身上的曲线太复杂，根本没办法用“小学”学过的“底乘高除以二”那一套来算。（省字版：也就是没有现成的公式来实现计算。）</p><p>怎么办？咱们换个思路。</p><p>你闭上眼睛，随手撒下一些大米，撒得足够均匀。撒完后，仔细数一数：有多少米粒落在龙上？又有多少撒在整个屏幕上？假如龙区域的米粒占了总数的1/4，那是不是可以说，龙的面积也大概就是屏幕的1/4？而手机屏幕的形状是规则的，我们只需要查一下手机厂商的官方数据，就可以知道面积了——这样一来龙的面积也就知道了。</p><p>你可能还会觉得一颗一颗数米粒太麻烦了，那还可以用我们前面教的编程思维再做一次转换，不算米粒的数量，而是<strong>算重量</strong>。米粒越多当然就越重。拿个电子秤，称一下屏幕上全部米粒的重量，再称一下龙区域那部分米的重量，两个重量一比较，也能算出来龙的面积。</p><figure><img src="/assets/sssss-CLGqTlXr.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>是不是有点听蒙了？别着急，我再带你看一个更简单的情况。想象一下，如果一张纸上有两个圆圈，一大一小，我们闭上眼睛往纸上撒一把大米，肯定是撒到大圆圈里的比较多对吧？</p><p>假如大圆和小圆的<strong>面积之比</strong>是2:1，只要你撒的米粒足够多、足够均匀，那么这两个圆圈里米粒的<strong>数量</strong>也会是2:1，对吧。你看，这样我们就把图形的面积转化成米粒的数量了。这个例子理解了，那上面比例、重量方法都能理解了。</p><p>怎么样，很神奇吧！不需要使用公式，拿一把大米，就算出了熊猫的面积。以后做数学的时候，是不是也可以随身带一包大米了呢？</p><h2 id="_2-这个魔法方法有个名字" tabindex="-1"><a class="header-anchor" href="#_2-这个魔法方法有个名字"><span>2. 这个魔法方法有个名字</span></a></h2><figure><img src="/assets/%E8%92%99%E7%89%B9%E5%8D%A1%E6%B4%9B-D4wPtGA5.png" alt="蒙特卡洛" tabindex="0" loading="lazy"><figcaption>蒙特卡洛</figcaption></figure><p>前面说的方法，其实有个正式的名字，叫做：<strong>蒙特卡洛法</strong>。</p><p>听起来像哪个大魔术师的名字？其实它不是人的名字，而是欧洲的一个赌城——<strong>蒙特卡洛</strong>。为什么一个正经算法，会和赌博扯上关系呢？这背后还有个传奇故事。（省字版：赌博不是什么好事！）</p><p>20世纪40年代，美国科学家在搞一个超级工程——制造氢弹。但中途遇到了一个天大的数学难题，这个数学难题没有现成的公式可以套用。算不出来这个数学题，氢弹就造不出来了。</p><figure><img src="/assets/%E4%B9%8C%E6%8B%89%E5%A7%86-h2T1XusS.png" alt="乌拉姆·动漫画像" tabindex="0" loading="lazy"><figcaption>乌拉姆·动漫画像</figcaption></figure><p>这时候，一位叫<strong>乌拉姆</strong>的数学家，想到一个好主意。突然就想：能不能算一下，自己拿到一手特殊的牌面的概率呢。如果要用公式来硬算，肯定会特别特别难。于是他就换了个思路，既然硬算算不出来，我不如用计算机模拟抓牌1万次，然后数一数其中有多少次拿到了这种特殊的牌面，不就行了吗？</p><p><s>在打牌时灵机一动：我想知道某种特殊牌型出现的几率，如果用公式算太麻烦，干脆用计算机模拟一万次随机发牌，看结果出现了多少次，不就得出概率了吗？</s></p><p>有没有感觉到什么？——这个思路就跟前面我说的，用撒米的方法算面积是一样的，就是用<strong>模拟实验</strong>，来<strong>替代数学计算</strong>，求得结果。制造氢弹的那个计算，也可以使用这样的方法。</p><p>诶，这个主意很棒啊！</p><figure><img src="/assets/raw-20250420194044183-CRGm1OtB.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>于是，乌拉姆就赶紧跑过去跟另一位数学家<strong>冯·诺依曼</strong>说了他的灵感。冯·诺依曼是当时世界上计算机玩得最溜的人之一，美国第一台电子计算机能制造出来，就离不开冯·诺依曼的研究。</p><p>听到乌拉姆的建议，冯·诺依曼赶紧在计算机上编好了程序，问题果然解决了，<strong>氢弹也顺利制造出来了</strong>。</p><p>这个方法这么厉害，该起个什么名字呢？有一位数学家就说：干脆起名叫<strong>蒙特卡洛</strong>吧。这种方法本身就是<strong>受到牌局的启发</strong>而想出来的，它也会模拟各种各样的情况，乍一看跟翻来覆去投注赌博差不多。用蒙特卡洛这个赌城的名字来命名，多合适啊。</p><p>然后，它就真的叫这个名字了。听起来有点随便，也有些不光彩是不是呀？但那也没办法，现在大家都这么叫，改都没法改了。</p><p><s>从此，这种“靠大量随机模拟来找出答案”的方法，就有了个名字——蒙特卡洛法。</s></p><h2 id="_3-那-π-跟这有啥关系呢" tabindex="-1"><a class="header-anchor" href="#_3-那-π-跟这有啥关系呢"><span>3. 那 π 跟这有啥关系呢？</span></a></h2><p>不管怎样，咱们现在有了蒙特卡洛算法这么厉害的工具了，那它又是怎么计算 π 的值呢？</p><p>好问题！我们回到刚才撒米的实验，再换一个“圆中画方”的套路。</p><figure><img src="/assets/raw-20250420201012510-8oYavUsD.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>聪明的你可能已经想到了：你拿一张正方形纸，画个刚好能套在里面的圆。然后撒米粒，随便撒，越多越好。撒完后，分别数一下，落在圆里的有多少，落在整个正方形里的有多少。你就能知道圆的面积大约是多少。</p><p>因为你知道正方形的边长，也知道它的面积，还知道圆的直径是一样长……一个简单的除法，就能算出 π 的值啦！</p><p>这个过程就是一个<strong>用实验来估算数学常数</strong>的超有趣方法。也许你估不出 π 的几百位小数，但前几位大概率是靠谱的。而且，只用一堆米就能做到，是不是很酷？</p><h2 id="_4-小结-撒米不止是饭前仪式-它是计算的魔术棒" tabindex="-1"><a class="header-anchor" href="#_4-小结-撒米不止是饭前仪式-它是计算的魔术棒"><span>4. 小结：撒米不止是饭前仪式，它是计算的魔术棒！</span></a></h2><p>你可能没想到，祖冲之、冯·诺依曼和你这颗看起来普普通通的大米，居然都能在圆周率的问题上碰头！这就是科学的魅力。</p><p>记住这个神奇的思路：<strong>模拟替代计算、实验替代公式</strong>，这也是编程思维的一种。也许将来有一天，你写的程序，能解决一些大人们都搞不定的事——就像当年的那些科学家一样。</p><p>省字版：<strong>蒙特卡洛算法就是“用大量随机尝试，逼近正确答案”的一种方法，越多尝试，越接近真相。</strong></p><p><strong>应用场景</strong>：</p><ul><li>估算圆周率 π（比如“撒米粒”的方法）</li><li>计算复杂积分</li><li>金融风险评估</li><li>游戏 AI 走棋（比如围棋中的 MCTS，蒙特卡洛树搜索）</li><li>模拟粒子轨迹、核反应、天气系统……</li></ul>`,45)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};